var generatedSessionID = regexp.MustCompile(`^ses_[0-9a-f]{8}-[0-9a-f]{4}-7[0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$`)

// Expected values come from posthog-js's deterministicPrefixedId.
func TestDeterministicSessionIDMatchesReference(t *testing.T) {
	for input, want := range map[string]string{
		"0190f0e8-7a6b-7c3d-9e4f-5a6b7c8d9e0f": "ses_6df45f0102a182bcd5e8dd5dad6c65a0",
		"session-123":                          "ses_346bdc9a6b5cb06913bb476a65021eb5",
		"a":                                    "ses_8601ec8c0eec655f4ec03fd0b1129ba7",
		"":                                     "ses_84222325cbf29ce4805967715e2fab98",
		"MCP session/with spaces":              "ses_f7a86f830acb61f8cea1de7b3d66eefc",
		"é-ünï":                                "ses_f52aeeca2d955f05d88a791a4ead6a71",
	} {
		assert.Equal(t, want, deterministicSessionID(input), "input %q", input)
	}
}

type fakeClock struct {
	mu  sync.Mutex
	now time.Time
}

func (c *fakeClock) Now() time.Time {
	c.mu.Lock()
	defer c.mu.Unlock()
	return c.now
}

func (c *fakeClock) advance(d time.Duration) {
	c.mu.Lock()
	defer c.mu.Unlock()
	c.now = c.now.Add(d)
}

func withClock(clock *fakeClock) Option {
	return func(cfg *config) { cfg.now = clock.Now }
}

func TestGeneratedSessionRotatesAfterInactivity(t *testing.T) {
	queue := &fakeQueue{}
	clock := &fakeClock{now: time.Date(2026, 1, 1, 9, 0, 0, 0, time.UTC)}
	server := newServer()
	Instrument(server, posthogmcp.New(queue), withClock(clock))
	addWeatherTool(server, nil)
	client := connectInMemory(t, server)

	steps := []struct {
		name         string
		idleBefore   time.Duration
		sameAsBefore bool
	}{
		{name: "first call", sameAsBefore: false},
		{name: "shortly after", idleBefore: time.Minute, sameAsBefore: true},
		{name: "exactly at the timeout", idleBefore: sessionInactivityTimeout, sameAsBefore: true},
		{name: "activity extends the session", idleBefore: 29 * time.Minute, sameAsBefore: true},
		{name: "past the timeout", idleBefore: sessionInactivityTimeout + time.Second, sameAsBefore: false},
	}
	var previous string
	for i, step := range steps {
		clock.advance(step.idleBefore)
		_, err := client.CallTool(t.Context(), &mcpsdk.CallToolParams{Name: "weather", Arguments: map[string]any{"city": "Melbourne"}})
		require.NoError(t, err, step.name)

		current, _ := queue.toolCalls()[i].Properties["$session_id"].(string)
		assert.Regexp(t, generatedSessionID, current, step.name)
		if i > 0 {
			assert.Equal(t, step.sameAsBefore, current == previous, step.name)
		}
		previous = current
	}
}

func TestConnectionsToOneServerGetDifferentSessions(t *testing.T) {
	queue := &fakeQueue{}
	server := newServer()
	Instrument(server, posthogmcp.New(queue))
	addWeatherTool(server, nil)
	first, second := connectInMemory(t, server), connectInMemory(t, server)

	var wg sync.WaitGroup
	for _, client := range []*mcpsdk.ClientSession{first, second, first, second} {
		wg.Go(func() {
			_, err := client.CallTool(t.Context(), &mcpsdk.CallToolParams{Name: "weather", Arguments: map[string]any{"city": "Melbourne"}})
			assert.NoError(t, err)
		})
	}
	wg.Wait()

	distinct := map[any]bool{}
	for _, capture := range queue.toolCalls() {
		distinct[capture.Properties["$session_id"]] = true
	}
	assert.Len(t, distinct, 2)
}

func TestIdleGeneratedSessionsAreEvicted(t *testing.T) {
	clock := &fakeClock{now: time.Date(2026, 1, 1, 9, 0, 0, 0, time.UTC)}
	resolver := newSessionResolver(clock.Now)
	idle, active := &mcpsdk.ServerSession{}, &mcpsdk.ServerSession{}
	resolver.resolve(idle, false)
	resolver.resolve(active, false)
	require.Len(t, resolver.generated, 2)

	clock.advance(sessionInactivityTimeout - time.Minute)
	resolver.resolve(active, false)
	clock.advance(2 * time.Minute)
	resolver.resolve(active, false)

	assert.Len(t, resolver.generated, 1)
	assert.Contains(t, resolver.generated, active)
}

func TestRequestScopedSessionsAreNotRetained(t *testing.T) {
	resolver := newSessionResolver(time.Now)
	ids := map[string]bool{}
	for range 10_000 {
		id := resolver.resolve(&mcpsdk.ServerSession{}, true)
		assert.Regexp(t, generatedSessionID, id)
		ids[id] = true
	}

	assert.Len(t, ids, 10_000)
	assert.Empty(t, resolver.generated)
}

func TestGeneratedSessionsAreCappedOldestFirst(t *testing.T) {
	clock := &fakeClock{now: time.Date(2026, 1, 1, 9, 0, 0, 0, time.UTC)}
	resolver := newSessionResolver(clock.Now)
	oldest := &mcpsdk.ServerSession{}
	resolver.resolve(oldest, false)
	for range maxGeneratedSessions {
		clock.advance(time.Millisecond)
		resolver.resolve(&mcpsdk.ServerSession{}, false)
	}

	assert.Len(t, resolver.generated, maxGeneratedSessions)
	_, retained := resolver.generated[oldest]
	assert.False(t, retained)
}

// A stateless HTTP request is the one transport whose sessions are request
// scoped, and go-sdk marks it with request Extra and an empty session id.
func TestStatelessHTTPRequestsAreRequestScoped(t *testing.T) {
	server := mcpsdk.NewServer(
		&mcpsdk.Implementation{Name: "test-server", Version: "1.0.0"},
		&mcpsdk.ServerOptions{GetSessionID: func() string { return "" }},
	)
	var mu sync.Mutex
	var seen []string
	server.AddReceivingMiddleware(func(next mcpsdk.MethodHandler) mcpsdk.MethodHandler {
		return func(ctx context.Context, method string, req mcpsdk.Request) (mcpsdk.Result, error) {
			if call, ok := req.(*mcpsdk.CallToolRequest); ok {
				mu.Lock()
				seen = append(seen, fmt.Sprintf("id=%q extra=%t", call.Session.ID(), call.Extra != nil))
				mu.Unlock()
			}
			return next(ctx, method, req)
		}
	})
	addWeatherTool(server, nil)
	httpServer := httptest.NewServer(mcpsdk.NewStreamableHTTPHandler(func(*http.Request) *mcpsdk.Server { return server }, &mcpsdk.StreamableHTTPOptions{Stateless: true}))
	t.Cleanup(httpServer.Close)
	client := mcpsdk.NewClient(&mcpsdk.Implementation{Name: "http-client", Version: "1.0.0"}, nil)
	session, err := client.Connect(t.Context(), &mcpsdk.StreamableClientTransport{Endpoint: httpServer.URL}, nil)
	require.NoError(t, err)
	t.Cleanup(func() { _ = session.Close() })

	_, err = session.CallTool(t.Context(), &mcpsdk.CallToolParams{Name: "weather", Arguments: map[string]any{"city": "Melbourne"}})
	require.NoError(t, err)

	mu.Lock()
	defer mu.Unlock()
	assert.Equal(t, []string{`id="" extra=true`}, seen)
}

package posthogmcpsdk

import (
	"context"
	"errors"
	"sync"
	"sync/atomic"
	"testing"
	"time"

	mcpsdk "github.com/modelcontextprotocol/go-sdk/mcp"
	"github.com/stretchr/testify/assert"
)

func callRequest(name string) *mcpsdk.CallToolRequest {
	return &mcpsdk.CallToolRequest{Session: &mcpsdk.ServerSession{}, Params: &mcpsdk.CallToolParamsRaw{Name: name}}
}

func listing(names ...string) *mcpsdk.ListToolsResult {
	tools := make([]*mcpsdk.Tool, len(names))
	for i, name := range names {
		tools[i] = &mcpsdk.Tool{Name: name, Description: "about " + name, InputSchema: map[string]any{"type": "object"}}
	}
	return &mcpsdk.ListToolsResult{Tools: tools}
}

func TestCatalogListingDuringWalkDoesNotStartAnother(t *testing.T) {
	catalog := newToolCatalog([]analyticsArgument{contextParameter}, time.Now)
	walkStarted := make(chan struct{})
	release := make(chan struct{})
	var lists atomic.Int32
	next := func(context.Context, string, mcpsdk.Request) (mcpsdk.Result, error) {
		if lists.Add(1) == 1 {
			close(walkStarted)
			<-release
		}
		return listing("known"), nil
	}

	var lookups sync.WaitGroup
	lookups.Go(func() { _, _ = catalog.lookup(t.Context(), next, callRequest("first")) })
	<-walkStarted
	catalog.advertise(catalog.generation(), listing("known").Tools)
	lookups.Go(func() { _, _ = catalog.lookup(t.Context(), next, callRequest("second")) })
	close(release)
	lookups.Wait()

	assert.Equal(t, int32(1), lists.Load())
}

func TestCatalogRetriesAFailedWalk(t *testing.T) {
	for _, test := range []struct {
		name    string
		failing mcpsdk.MethodHandler
		wantErr string
	}{
		{
			name: "inner error",
			failing: func(context.Context, string, mcpsdk.Request) (mcpsdk.Result, error) {
				return nil, errors.New("transient")
			},
			wantErr: "posthogmcpsdk: tools/list through inner handler: transient",
		},
		{
			name: "unexpected result type",
			failing: func(context.Context, string, mcpsdk.Request) (mcpsdk.Result, error) {
				return &mcpsdk.CallToolResult{}, nil
			},
			wantErr: "posthogmcpsdk: tools/list through inner handler returned *mcp.CallToolResult",
		},
		{
			name: "inner panic",
			failing: func(context.Context, string, mcpsdk.Request) (mcpsdk.Result, error) {
				panic("inner tools/list panic")
			},
			wantErr: "posthogmcpsdk: tools/list through inner handler panicked (string)",
		},
	} {
		t.Run(test.name, func(t *testing.T) {
			catalog := newToolCatalog([]analyticsArgument{contextParameter}, time.Now)
			var failing atomic.Bool
			failing.Store(true)
			next := func(ctx context.Context, method string, req mcpsdk.Request) (mcpsdk.Result, error) {
				if failing.Load() {
					return test.failing(ctx, method, req)
				}
				return listing("tool"), nil
			}

			info, err := catalog.lookup(t.Context(), next, callRequest("tool"))
			assert.Equal(t, toolInfo{}, info)
			assert.EqualError(t, err, test.wantErr)

			failing.Store(false)
			info, err = catalog.lookup(t.Context(), next, callRequest("tool"))
			assert.Equal(t, toolInfo{registered: true, description: "about tool", injected: []string{"context"}}, info)
			assert.NoError(t, err)
		})
	}
}

// More pages will not appear on a retry, so a capped walk is remembered like a
// complete one; otherwise every unknown-tool call would list 100 pages again.
func TestCatalogRemembersACappedWalk(t *testing.T) {
	catalog := newToolCatalog([]analyticsArgument{contextParameter}, time.Now)
	var lists atomic.Int32
	next := func(context.Context, string, mcpsdk.Request) (mcpsdk.Result, error) {
		lists.Add(1)
		return &mcpsdk.ListToolsResult{NextCursor: "more"}, nil
	}

	_, err := catalog.lookup(t.Context(), next, callRequest("missing"))
	assert.EqualError(t, err, "posthogmcpsdk: tools/list through inner handler has more than 100 pages")
	_, err = catalog.lookup(t.Context(), next, callRequest("missing"))
	assert.NoError(t, err)
	assert.Equal(t, int32(maxListingPages), lists.Load())
}

type panickingSchema struct{}

func (panickingSchema) MarshalJSON() ([]byte, error) { panic("schema panic") }

func TestCatalogPropagatesItsOwnPanicAndStaysRetryable(t *testing.T) {
	catalog := newToolCatalog([]analyticsArgument{contextParameter}, time.Now)
	schema := any(panickingSchema{})
	next := func(context.Context, string, mcpsdk.Request) (mcpsdk.Result, error) {
		return &mcpsdk.ListToolsResult{Tools: []*mcpsdk.Tool{{Name: "tool", InputSchema: schema}}}, nil
	}

	assert.PanicsWithValue(t, "schema panic", func() { _, _ = catalog.lookup(t.Context(), next, callRequest("tool")) })

	schema = map[string]any{"type": "object"}
	info, err := catalog.lookup(t.Context(), next, callRequest("tool"))
	assert.Equal(t, toolInfo{registered: true, injected: []string{"context"}}, info)
	assert.NoError(t, err)
}

func TestCatalogForgetsMissesAfterTenSeconds(t *testing.T) {
	for _, test := range []struct {
		name      string
		elapsed   time.Duration
		wantLists int32
		wantInfo  toolInfo
	}{
		{name: "just before", elapsed: 10*time.Second - time.Nanosecond, wantLists: 1, wantInfo: toolInfo{}},
		{name: "at ten seconds", elapsed: 10 * time.Second, wantLists: 2, wantInfo: toolInfo{registered: true, description: "about added", injected: []string{"context"}}},
	} {
		t.Run(test.name, func(t *testing.T) {
			catalog := newToolCatalog([]analyticsArgument{contextParameter}, time.Now)
			now := time.Unix(1_700_000_000, 0)
			catalog.now = func() time.Time { return now }
			registered := listing()
			var lists atomic.Int32
			next := func(context.Context, string, mcpsdk.Request) (mcpsdk.Result, error) {
				lists.Add(1)
				return registered, nil
			}
			_, _ = catalog.lookup(t.Context(), next, callRequest("added"))

			registered = listing("added")
			now = now.Add(test.elapsed)
			info, err := catalog.lookup(t.Context(), next, callRequest("added"))

			assert.NoError(t, err)
			assert.Equal(t, test.wantInfo, info)
			assert.Equal(t, test.wantLists, lists.Load())
		})
	}
}

func TestCatalogRelearnsKnownToolsAfterTenSeconds(t *testing.T) {
	for _, test := range []struct {
		name      string
		elapsed   time.Duration
		wantLists int32
		wantInfo  toolInfo
	}{
		{name: "just before", elapsed: 10*time.Second - time.Nanosecond, wantLists: 0, wantInfo: toolInfo{registered: true, description: "about plan", injected: []string{"context"}}},
		{name: "at ten seconds", elapsed: 10 * time.Second, wantLists: 1, wantInfo: toolInfo{registered: true, description: "replaced"}},
	} {
		t.Run(test.name, func(t *testing.T) {
			catalog := newToolCatalog([]analyticsArgument{contextParameter}, time.Now)
			now := time.Unix(1_700_000_000, 0)
			catalog.now = func() time.Time { return now }
			catalog.advertise(catalog.generation(), listing("plan").Tools)

			var lists atomic.Int32
			next := func(context.Context, string, mcpsdk.Request) (mcpsdk.Result, error) {
				lists.Add(1)
				return &mcpsdk.ListToolsResult{Tools: []*mcpsdk.Tool{{
					Name:        "plan",
					Description: "replaced",
					InputSchema: map[string]any{"type": "object", "properties": map[string]any{"context": map[string]any{"type": "string"}}},
				}}}, nil
			}
			now = now.Add(test.elapsed)
			info, err := catalog.lookup(t.Context(), next, callRequest("plan"))

			assert.NoError(t, err)
			assert.Equal(t, test.wantInfo, info)
			assert.Equal(t, test.wantLists, lists.Load())
		})
	}
}

func TestCatalogListingKeepsRememberedMisses(t *testing.T) {
	catalog := newToolCatalog([]analyticsArgument{contextParameter}, time.Now)
