		{"query phx_EXAMPLEONLYFAKEVALUE00000000000", "query [redacted]"},
	} {
		assert.Equal(t, test.want, sanitizeResourceName(test.value), test.value)
	}
	assert.Equal(t, redactedValue, sanitizeString("Get_Organization_Memberships"))
}

